# Raising custom exceptions

print("=== Basic raise ===\n")

# Simple raise
def check_health(health):
    if health < 0:
        raise ValueError("Health cannot be negative!")
    if health > 100:
        raise ValueError("Health cannot exceed 100!")
    return f"Health: {health}"

try:
    print(check_health(80))
    print(check_health(-10))
except ValueError as e:
    print(f"Error: {e}")

print("\n=== Custom exception class ===\n")

# Custom exception class
class InvalidLevelError(Exception):
    """Raised when level is invalid"""
    pass

class CharacterError(Exception):
    """Base exception for character errors"""
    pass

class NameTooShortError(CharacterError):
    """Raised when character name is too short"""
    pass

class NameTooLongError(CharacterError):
    """Raised when character name is too long"""
    pass

# Using custom exceptions
def create_character(name, level):
    if len(name) < 3:
        raise NameTooShortError(f"Name '{name}' is too short (min 3 characters)")
    if len(name) > 20:
        raise NameTooLongError(f"Name '{name}' is too long (max 20 characters)")
    if not 1 <= level <= 100:
        raise InvalidLevelError(f"Level {level} must be between 1 and 100")
    return f"Character {name} created at level {level}"

try:
    print(create_character("Bob", 5))
    print(create_character("A", 50))
except NameTooShortError as e:
    print(f"Name error: {e}")
except NameTooLongError as e:
    print(f"Name error: {e}")
except InvalidLevelError as e:
    print(f"Level error: {e}")
except CharacterError as e:
    print(f"Character error: {e}")

print("\n=== Raising with custom messages ===\n")

class GameError(Exception):
    def __init__(self, message, code):
        self.message = message
        self.code = code
        super().__init__(message)

try:
    raise GameError("Not enough gold", 403)
except GameError as e:
    print(f"Error {e.code}: {e.message}")

