class InvalidItemError(Exception):
    pass

def add_to_inventory(item):
    if item == "":
        raise InvalidItemError("Invalid item: empty string")
    if any(char.isdigit() for char in item):
        raise InvalidItemError("Invalid item: contains numbers")
    return f"Added: {item}"

items = ["Sword", "", "Potion2", "Shield"]

for item in items:
    try:
        print(add_to_inventory(item))
    except InvalidItemError as e:
        print(f"Error: {e}")
